def quad(x):
    from itertools import combinations_with_replacement as cwr
    return np.column_stack([np.ones(len(x)), x, *[x[:, i] * x[:, j] for (i, j) in cwr(range(4), 2)]])

def err(f, y):
    w = np.linalg.pinv(f)
    r = y - f @ (w @ y)
    h = (f * w.T).sum(1)
    z = r / (1 - h)[:, None]
    return (np.round(np.abs(r).mean(0), 6), np.round(np.abs(z).mean(0), 6))

def cv(F, O):
    P = np.linalg.pinv(F, rcond=1e-09)
    h = (F * P.T).sum(1)
    return np.mean(np.abs((O - F @ (P @ O)) / (1 - h[:, None])))

def _quadratic(x):
    from itertools import combinations_with_replacement
    return np.column_stack((np.ones(len(x)), x, *(x[:, i] * x[:, j] for (i, j) in combinations_with_replacement(range(x.shape[1]), 2))))

def _temporal_basis(times, trajectories):
    from scipy.optimize import least_squares

    def basis(rates):
        return -np.expm1(-times[:, None] * rates)

    def residual(rates):
        u = basis(rates)
        coefficients = np.linalg.lstsq(u, trajectories.T, rcond=None)[0]
        return (u @ coefficients - trajectories.T).ravel()
    rates = least_squares(residual, [1.5, 0.22], bounds=([0.7, 0.025], [3.0, 0.65])).x
    return basis(rates)
